#!/usr/bin/env node
const { loadSales, formatTable, formatJson } = require('../src/report');
const [command, ...flags] = process.argv.slice(2);
if (command === 'report') {
  const rows = loadSales();
  console.log(flags.includes('--json') ? formatJson(rows) : formatTable(rows));
} else {
  console.error('usage: sales report [--json]');
  process.exit(1);
}
EOF
python3 - <<'EOF'
p='src/report.js'; s=open(p).read()
s=s.replace("module.exports = { loadSales, formatTable };","function formatJson(rows) {\n  return JSON.stringify(rows.map(({ region, units, revenue }) => ({ region, units, revenue })), null, 2);\n}\nmodule.exports = { loadSales, formatTable, formatJson };")
open(p,'w').write(s)
EOF
cat >> test/report.test.js <<'EOF'
test('report --json prints the same rows as JSON', () => {
  const out = execFileSync('node', [path.join(__dirname, '..', 'bin', 'sales.js'), 'report', '--json'], { encoding: 'utf8' });
  const rows = JSON.parse(out);
  assert.deepStrictEqual(rows, require('../data/sales.json'));
});
EOF
